/usr/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import {createTransferWorkspace,createProgressFeed} from './src/workspace.js';
let ws, detached=0, calls=0;
const feed=createProgressFeed({initialPacket:'cached',onDetach(){detached++;}});
ws=createTransferWorkspace({transport(){},onCancel(){},record(){},showQueued(){},recordProgress(){},showProgress(){calls++; ws.hide();}});
ws.select({id:'f',progressFeed:feed});
assert.equal(calls,1);
assert.equal(detached,1);
assert.equal(ws.snapshot().visitId,null);
feed.emit('later');
assert.equal(calls,1);
console.log('synchronous hide check passed');
EOF
node --check src/progress.js
git diff -- src/progress.js"
